import type { Bundle, FhirResource } from 'fhir/r4.js';
import type { Payer, Policy } from '../policy.js';
import { HTEST, SYSTEMS } from '../systems.js';
import { SCENARIOS, type ScenarioSpec } from './scenarios.js';

/**
 * Turns `scenarios.ts` into the committed prior-authorization dataset.
 *
 * Hand-authored rather than generated by Synthea (P3-D, "Why hand-authored"):
 * the notes are written against a stratum, the labels are written with them,
 * and every identifying field is synthetic by construction —
 *
 * - every resource carries `meta.security` `HTEST`;
 * - every `identifier.system` is under `https://example.org/`, and there is
 *   no NPI. P3-D planned NPI-shaped values that fail the check digit, but US
 *   Core 6.1.0's invariant `us-core-17` requires a valid check digit on any
 *   NPI, so a failing one breaks the profile the validator gates on, and a
 *   passing one could be a real provider's. US Core requires an identifier,
 *   not an NPI, so the practitioner and the supplier carry example.org ones;
 * - every `HumanName` part ends in digits;
 * - telephone numbers are 555-0100 to 555-0199, which NANPA reserves;
 * - addresses carry a city and a state and no postal code.
 *
 * `scripts/lint-data.mjs` checks each of those on the output.
 */

const US_CORE = 'http://hl7.org/fhir/us/core/StructureDefinition';
/**
 * Pinned, because an unversioned canonical resolves to whichever US Core the
 * validator has loaded, and loading PAS 2.2.1 brings 7.0.0 with it. CMS lists
 * 6.1.0 for the Prior Authorization API, and that is the version gated on.
 */
const US_CORE_VERSION = '6.1.0';
const PROFILES = {
  patient: `${US_CORE}/us-core-patient|${US_CORE_VERSION}`,
  practitioner: `${US_CORE}/us-core-practitioner|${US_CORE_VERSION}`,
  organization: `${US_CORE}/us-core-organization|${US_CORE_VERSION}`,
  coverage: `${US_CORE}/us-core-coverage|${US_CORE_VERSION}`,
  condition: `${US_CORE}/us-core-condition-problems-health-concerns|${US_CORE_VERSION}`,
} as const;

const THO = 'http://terminology.hl7.org/CodeSystem';
const EXAMPLE = 'https://example.org/fhir';
const CARE_TEAM_CLAIM_SCOPE =
  'http://hl7.org/fhir/us/davinci-pas/StructureDefinition/extension-careTeamClaimScope';
const PLACE_OF_SERVICE =
  'https://www.cms.gov/Medicare/Coding/place-of-service-codes/Place_of_Service_Code_Set';

/** The CMS short descriptors, unchanged (ADR 0008's notice). */
const SHORT_DESCRIPTOR: Record<ScenarioSpec['hcpcs'], string> = {
  E0601: 'Cont airway pressure device',
  E0470: 'Rad w/o backup non-inv intfc',
  K0823: 'Pwc gp 2 std cap chair',
  E0260: 'Hosp bed semi-electr w/ matt',
};

const security = (): { security: [typeof HTEST] } => ({ security: [{ ...HTEST }] });

function base64(text: string): string {
  return Buffer.from(text, 'utf8').toString('base64');
}

export interface AuthoredTask {
  readonly id: string;
  readonly description: string;
  readonly hcpcs: string;
  readonly stratum: string;
  readonly bundle: string;
  readonly requires: { readonly model: readonly ['live', 'replay'] };
  readonly findingAgreementMin: number;
}

export interface AuthoredLabel {
  readonly hcpcs: string;
  readonly stratum: string;
  readonly disposition: 'automated-approval' | 'refer-to-clinician';
  /**
   * Whether the agent is expected to assess the criteria at all. The
   * `administrative` stratum is referred on coverage before any model call,
   * so its criterion labels describe the evidence and are not graded.
   */
  readonly assessed: boolean;
  readonly criteria: Readonly<
    Record<string, { readonly status: string; readonly evidence: readonly string[] }>
  >;
}

export interface AuthoredDataset {
  /** Path, relative to the dataset directory, to file contents. */
  readonly files: ReadonlyMap<string, string>;
  readonly tasks: readonly AuthoredTask[];
  readonly labels: Readonly<Record<string, AuthoredLabel>>;
}

function taskId(spec: ScenarioSpec): string {
  return `pa-${spec.hcpcs.toLowerCase()}-${spec.stratum}`;
}

const STRATUM_SENTENCE: Record<ScenarioSpec['stratum'], string> = {
  'all-met-structured': 'every criterion is evidenced by a coded condition or a stated measurement',
  'all-met-narrative': "every criterion is evidenced, at least one only in the note's prose",
  'one-missing': 'one criterion has no evidence in the bundle',
  contradicted: 'the record states a value that fails a threshold',
  ambiguous: 'the evidence for one criterion is hedged or undated',
  administrative: 'the coverage is not active on the date of service',
};

function authorBundle(
  spec: ScenarioSpec,
  index: number,
  payer: Payer,
): { bundle: Bundle<FhirResource>; reference: (key: string) => string } {
  const slug = `${spec.hcpcs.toLowerCase()}-${spec.stratum}`;
  const n = String(index + 1).padStart(2, '0');
  const ids = {
    claim: `claim-${slug}`,
    patient: `patient-${slug}`,
    coverage: `coverage-${slug}`,
    practitioner: `practitioner-${slug}`,
    role: `role-${slug}`,
    supplier: `supplier-${slug}`,
    insurer: `insurer-${slug}`,
    condition: (key: string) => `condition-${slug}-${key}`,
    document: (key: string) => `doc-${slug}-${key}`,
  };
  const phone = (offset: number): string =>
    `217-555-01${String((index * 3 + offset) % 100).padStart(2, '0')}`;
  const plan = payer.plans.find((candidate) => candidate.id === spec.plan);
  if (plan === undefined) throw new Error(`no plan ${spec.plan}`);

  const conditionKeys = new Set(spec.diagnoses.map((diagnosis) => diagnosis.key));
  const reference = (key: string): string =>
    conditionKeys.has(key)
      ? `Condition/${ids.condition(key)}`
      : `DocumentReference/${ids.document(key)}`;

  const patientRef = { reference: `Patient/${ids.patient}` };
  const memberId = `CBK-M-${String(1000 + index + 1)}`;

  const claim: FhirResource = {
    resourceType: 'Claim',
    id: ids.claim,
    meta: security(),
    identifier: [{ system: `${EXAMPLE}/sid/submission`, value: `SUB-${slug}` }],
    status: 'active',
    type: { coding: [{ system: `${THO}/claim-type`, code: 'professional' }] },
    use: 'preauthorization',
    patient: patientRef,
    created: spec.created,
    insurer: { reference: `Organization/${ids.insurer}` },
    provider: { reference: `Organization/${ids.supplier}` },
    priority: { coding: [{ system: SYSTEMS.PROCESS_PRIORITY, code: spec.priority }] },
    careTeam: [
      {
        // PAS requires the scope flag and a PractitionerRole or Organization
        // here; neither is an X12 element, so the bundle carries both.
        extension: [{ url: CARE_TEAM_CLAIM_SCOPE, valueBoolean: true }],
        sequence: 1,
        provider: { reference: `PractitionerRole/${ids.role}` },
      },
    ],
    supportingInfo: spec.notes.map((note, i) => ({
      sequence: i + 1,
      category: { coding: [{ system: `${THO}/claiminformationcategory`, code: 'attachment' }] },
      valueReference: { reference: `DocumentReference/${ids.document(note.key)}` },
    })),
    diagnosis: spec.diagnoses.map((diagnosis, i) => ({
      sequence: i + 1,
      diagnosisCodeableConcept: {
        coding: [{ system: SYSTEMS.ICD10CM, code: diagnosis.icd10cm, display: diagnosis.display }],
      },
    })),
    insurance: [{ sequence: 1, focal: true, coverage: { reference: `Coverage/${ids.coverage}` } }],
    item: [
      {
        sequence: 1,
        careTeamSequence: [1],
        diagnosisSequence: spec.diagnoses.map((_, i) => i + 1),
        informationSequence: spec.notes.map((_, i) => i + 1),
        productOrService: {
          coding: [
            { system: SYSTEMS.HCPCS, code: spec.hcpcs, display: SHORT_DESCRIPTOR[spec.hcpcs] },
          ],
        },
        servicedDate: spec.serviceDate,
        quantity: { value: 1 },
        locationCodeableConcept: {
          coding: [{ system: PLACE_OF_SERVICE, code: '12', display: 'Home' }],
        },
      },
    ],
  };

  const patient: FhirResource = {
    resourceType: 'Patient',
    id: ids.patient,
    meta: { ...security(), profile: [PROFILES.patient] },
    identifier: [
      {
        type: { coding: [{ system: `${THO}/v2-0203`, code: 'MB' }] },
        system: `${EXAMPLE}/sid/member-id`,
        value: memberId,
      },
    ],
    active: true,
    name: [{ use: 'official', family: spec.patient.family, given: [spec.patient.given] }],
    telecom: [{ system: 'phone', value: phone(0), use: 'home' }],
    gender: spec.patient.gender,
    birthDate: spec.patient.birthDate,
    address: [{ use: 'home', city: spec.patient.city, state: spec.patient.state, country: 'US' }],
  };

  const coverage: FhirResource = {
    resourceType: 'Coverage',
    id: ids.coverage,
    meta: { ...security(), profile: [PROFILES.coverage] },
    identifier: [
      {
        type: { coding: [{ system: `${THO}/v2-0203`, code: 'MB' }] },
        system: `${EXAMPLE}/sid/member-id`,
        value: memberId,
      },
    ],
    status: 'active',
    subscriberId: memberId,
    // The member is their own subscriber. PAS's `self-beneficiary` invariant
    // reads `self` in X12's code list, so the subscriber is stated instead.
    subscriber: patientRef,
    beneficiary: patientRef,
    relationship: { coding: [{ system: `${THO}/subscriber-relationship`, code: 'self' }] },
    period: { start: '2026-01-01', end: spec.coverageEnd },
    payor: [{ reference: `Organization/${ids.insurer}` }],
    class: [
      {
        type: { coding: [{ system: `${THO}/coverage-class`, code: 'plan' }] },
        value: plan.id,
        name: plan.name,
      },
    ],
  };

  const practitioner: FhirResource = {
    resourceType: 'Practitioner',
    id: ids.practitioner,
    meta: { ...security(), profile: [PROFILES.practitioner] },
    identifier: [{ system: `${EXAMPLE}/sid/practitioner-id`, value: `PRAC-${n}` }],
    active: true,
    name: [{ family: spec.prescriber.family, given: [spec.prescriber.given], prefix: ['Dr'] }],
    telecom: [{ system: 'phone', value: phone(1), use: 'work' }],
  };

  const role: FhirResource = {
    resourceType: 'PractitionerRole',
    id: ids.role,
    meta: security(),
    active: true,
    practitioner: { reference: `Practitioner/${ids.practitioner}` },
    telecom: [{ system: 'phone', value: phone(1), use: 'work' }],
  };

  const supplier: FhirResource = {
    resourceType: 'Organization',
    id: ids.supplier,
    meta: { ...security(), profile: [PROFILES.organization] },
    identifier: [{ system: `${EXAMPLE}/sid/supplier-id`, value: `SUP-${n}` }],
    active: true,
    type: [{ coding: [{ system: `${THO}/organization-type`, code: 'prov' }] }],
    name: `Synthetic Home Medical Supply ${n}`,
    telecom: [{ system: 'phone', value: phone(2), use: 'work' }],
    address: [{ use: 'work', city: spec.patient.city, state: spec.patient.state, country: 'US' }],
  };

  const insurer: FhirResource = {
    resourceType: 'Organization',
    id: ids.insurer,
    meta: { ...security(), profile: [PROFILES.organization] },
    identifier: [{ ...payer.payer.identifier }],
    active: true,
    type: [{ coding: [{ system: `${THO}/organization-type`, code: 'pay' }] }],
    name: payer.payer.name,
  };

  const conditions: FhirResource[] = spec.diagnoses.map((diagnosis) => ({
    resourceType: 'Condition',
    id: ids.condition(diagnosis.key),
    meta: { ...security(), profile: [PROFILES.condition] },
    clinicalStatus: { coding: [{ system: `${THO}/condition-clinical`, code: 'active' }] },
    verificationStatus: { coding: [{ system: `${THO}/condition-ver-status`, code: 'confirmed' }] },
    category: [{ coding: [{ system: `${THO}/condition-category`, code: 'problem-list-item' }] }],
    code: {
      coding: [{ system: SYSTEMS.ICD10CM, code: diagnosis.icd10cm, display: diagnosis.display }],
    },
    subject: patientRef,
    onsetDateTime: diagnosis.onset,
  }));

  const documents: FhirResource[] = spec.notes.map((note) => ({
    resourceType: 'DocumentReference',
    id: ids.document(note.key),
    meta: security(),
    status: 'current',
    type: {
      coding: [{ system: `${EXAMPLE}/CodeSystem/document-type`, code: 'clinical-note' }],
      text: note.description,
    },
    subject: patientRef,
    ...(note.date === undefined ? {} : { date: `${note.date}T12:00:00Z` }),
    author: [{ reference: `Practitioner/${ids.practitioner}` }],
    description: note.description,
    content: [
      { attachment: { contentType: 'text/plain; charset=utf-8', data: base64(note.text) } },
    ],
  }));

  const resources = [
    claim,
    patient,
    coverage,
    practitioner,
    role,
    supplier,
    insurer,
    ...conditions,
    ...documents,
  ];

  return {
    reference,
    bundle: {
      resourceType: 'Bundle',
      id: `bundle-${slug}`,
      meta: security(),
      identifier: { system: `${EXAMPLE}/sid/submission`, value: `SUB-${slug}` },
      type: 'collection',
      timestamp: spec.created,
      entry: resources.map((resource) => ({
        fullUrl: `${EXAMPLE}/${resource.resourceType}/${resource.id ?? ''}`,
        resource,
      })),
    },
  };
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}

/**
 * The whole dataset: 24 task files, 24 bundles, and the labels.
 *
 * `policies` is used only to check that each scenario's labels name exactly
 * its policy's criteria, so a renamed criterion fails here and not in a
 * grader after a recording has been spent on it.
 */
export function authorDataset(payer: Payer, policies: readonly Policy[]): AuthoredDataset {
  const files = new Map<string, string>();
  const tasks: AuthoredTask[] = [];
  const labels: Record<string, AuthoredLabel> = {};

  SCENARIOS.forEach((spec, index) => {
    const policy = policies.find((candidate) => candidate.hcpcs === spec.hcpcs);
    if (policy === undefined) throw new Error(`no policy for ${spec.hcpcs}`);
    const expected = policy.criteria.map((criterion) => criterion.id).sort();
    const labelled = Object.keys(spec.labels).sort();
    if (expected.join() !== labelled.join()) {
      throw new Error(
        `${taskId(spec)} labels ${labelled.join()} but the policy has ${expected.join()}`,
      );
    }

    const id = taskId(spec);
    const bundlePath = `bundles/${id}.bundle.json`;
    const { bundle, reference } = authorBundle(spec, index, payer);
    const approved =
      spec.stratum !== 'administrative' &&
      Object.values(spec.labels).every((label) => label.status === 'met');

    const task: AuthoredTask = {
      id,
      description: `${spec.hcpcs}, ${spec.stratum}: ${STRATUM_SENTENCE[spec.stratum]}.`,
      hcpcs: spec.hcpcs,
      stratum: spec.stratum,
      bundle: bundlePath,
      requires: { model: ['live', 'replay'] },
      findingAgreementMin: 0.75,
    };

    labels[id] = {
      hcpcs: spec.hcpcs,
      stratum: spec.stratum,
      disposition: approved ? 'automated-approval' : 'refer-to-clinician',
      assessed: spec.stratum !== 'administrative',
      criteria: Object.fromEntries(
        policy.criteria.map((criterion) => {
          const label = spec.labels[criterion.id];
          if (label === undefined) throw new Error(`${id} has no label for ${criterion.id}`);
          return [criterion.id, { status: label.status, evidence: label.evidence.map(reference) }];
        }),
      ),
    };

    tasks.push(task);
    files.set(`${id}.json`, json(task));
    files.set(bundlePath, json(bundle));
  });

  files.set(
    'bundles/labels.json',
    json({
      description:
        'The correct disposition and per-criterion label for each request, written with the ' +
        'scenarios in packages/prior-auth/src/dataset/scenarios.ts before any model read a bundle. ' +
        'The suite report prints the sha256 of this file.',
      labels,
    }),
  );

  return { files, tasks, labels };
}
